function knowledge(){const docs=state.docs.filter(d=>(state.docScope==='all'||d.scope===state.docScope)&&`${d.title} ${d.product} ${d.topic}`.toLowerCase().includes(state.docSearch.toLowerCase()));return `<div class="content">${heading('매뉴얼·회사 지식','답변의 근거가 되는 문서를 제품과 공개 범위별로 관리하세요.',`<button class="btn primary" data-action="add-doc" ${isReadonly()?'disabled':''}>${icon('plus')}지식 등록</button>`)}<div class="summary-tiles"><article><span>등록 문서</span><strong>${state.docs.length}<small>개</small></strong></article><article><span>공개 답변에 사용</span><strong>${state.docs.filter(d=>d.scope==='public'&&d.active).length}<small>개</small></strong></article><article><span>사내 전용 자료</span><strong>${state.docs.filter(d=>d.scope==='internal').length}<small>개</small></strong></article><article><span>활성 문서</span><strong>${state.docs.filter(d=>d.active).length}<small>개</small></strong></article></div><div class="info-panel">${icon('shield')}<span><strong>최신 버전과 공개 범위를 기준으로 답변합니다.</strong><p>사내 전용 문서와 거래처별 특별 조건은 고객 공개 답변의 근거에서 제외합니다.</p></span></div><section class="panel"><div class="table-toolbar"><div class="search-field">${icon('search')}<input aria-label="매뉴얼 검색" data-input="doc-search" value="${esc(state.docSearch)}" placeholder="문서명, 모델명, 주제 검색"></div><select class="select" data-input="doc-scope" aria-label="문서 공개 범위"><option value="all">모든 공개 범위</option><option value="public" ${state.docScope==='public'?'selected':''}>공개 답변 사용</option><option value="internal" ${state.docScope==='internal'?'selected':''}>사내 전용</option></select></div><div class="table-scroll"><table><thead><tr><th>문서·제품</th><th>주제</th><th>공개 범위</th><th>버전</th><th>상태</th><th>관리</th></tr></thead><tbody id="doc-table">${docRows(docs)}</tbody></table></div><div class="panel-note">모든 문서와 모델명은 설명용 샘플입니다. 실제 장비 사용 지침으로 사용할 수 없습니다.</div></section><section class="panel spacing"><header><div><h2>문서가 답변의 근거가 되기까지</h2><p>자료 정리와 승인, 답변 근거 확인을 한 흐름으로 관리합니다.</p></div></header><div class="process-line">${[['file','문서 등록','제품·주제·공개 범위 지정'],['book','내용 추출·검색 구성','텍스트 자료를 검색 단위로 분할'],['shield','문서 승인','현재 버전과 사용 범위 확인'],['message','답변 활용','관련 구절과 출처를 함께 표시']].map(([i,t,d])=>`<div>${icon(i)}<strong>${t}</strong><small>${d}</small></div>`).join('')}</div></section>${footer()}</div>`;}
function docRows(docs){return docs.map(d=>`<tr><td><button class="doc-link" data-action="doc" data-id="${d.id}">${icon('file')}<span><strong>${esc(d.title)}</strong><small>${d.kind} · ${esc(d.product)} · 샘플 문서</small></span></button></td><td>${esc(d.topic)}</td><td>${badge(d.scope==='public'?'공개 답변 사용':'사내 전용',d.scope==='public'?'blue':'')}</td><td>v${esc(d.version)}</td><td>${badge(d.active?'활성':'비활성',d.active?'':'amber')}</td><td><button class="text-button" data-action="toggle-doc" data-id="${d.id}" ${state.role!=='admin'?'disabled':''}>${d.active?'비활성화':'활성화'}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">검색 결과가 없습니다.</td></tr>';}
function docModal(id){const d=state.docs.find(d=>d.id===Number(id));if(!d)return;if(d.scope==='internal'&&state.role!=='admin'){toast('사내 전용 샘플 문서는 관리자 권한으로 확인할 수 있습니다.');return;}modal(d.title,`<div class="document-meta">${badge(d.kind)}${badge(d.scope==='public'?'공개 답변 사용':'사내 전용',d.scope==='public'?'blue':'')}<span>${esc(d.product)} · v${esc(d.version)} · ${esc(d.page)}쪽</span></div><div class="document-preview"><header><span>${icon('file')}설명용 가상 문서</span><strong>${esc(d.title)}</strong><small>${esc(d.updated)} · 승인된 버전 v${esc(d.version)}</small></header><p>${esc(d.text)}</p></div><div class="info-panel compact">${icon('shield')}<p>실제 제조사 문서가 아닌 제품 흐름 설명용 샘플입니다. 문서의 공개 범위와 활성 상태를 확인해 답변에 적용합니다.</p></div>`,`${d.previous&&state.role==='admin'?`<button class="btn" data-action="rollback-doc" data-id="${d.id}">${icon('refresh')}이전 버전으로 되돌리기</button>`:''}<button class="btn primary" data-action="close">확인</button>`,true);}
function feedback(){return `<div class="content">${heading('수정 답변 검토','발송한 답변의 수정 내용을 검토하고, 재사용 가능한 지식만 승인하세요.')}<div class="info-panel">${icon('shield')}<span><strong>고객에게 보낸 답변이 바로 공통 지식이 되지는 않습니다.</strong><p>문서 충돌과 고객별 조건을 확인한 뒤 별도 승인합니다. 모델 가중치 학습은 이 데모의 범위에 포함하지 않습니다.</p></span></div><div class="feedback-list">${state.feedback.map(f=>`<article class="panel feedback-card"><header><div><h2>${esc(f.title)}</h2><p>문의 #RV-${f.thread} · ${esc(f.owner)} · ${esc(f.reason)}</p></div>${badge(({pending:'반영 검토 대기',accepted:'지식 반영 완료',held:'반영 보류',excluded:'공통 지식 제외'})[f.status],f.status==='pending'?'blue':f.status==='accepted'?'':f.status==='held'?'amber':'')}</header><div class="diff-grid"><div><span>수정 전</span><p>${esc(f.before)}</p></div><div><span>수정 후</span><p>${esc(f.after)}</p></div></div><footer><span class="risk-note ${f.risk!=='clear'?'warning':''}">${icon(f.risk==='clear'?'checkCircle':'shield')}${f.risk==='clear'?'공개 문서와 일치 · 고객별 조건 없음':f.risk==='conflict'?'공식 문서와 충돌 · 그대로 반영할 수 없음':'개인 정보·고객별 특별 조건은 공통 지식 제외'}</span><div><button class="btn" data-action="feedback-view" data-id="${f.id}">검토 상세</button>${f.status==='pending'?`<button class="btn pale" data-action="feedback-approve" data-id="${f.id}" ${state.role!=='admin'?'disabled':''}>지식 반영 검토</button>`:''}</div></footer></article>`).join('')}</div>${footer()}</div>`;}
function automation(){const e=state.evaluation,eligible=!!e&&e.passed>=state.threshold&&e.critical===0;return `<div class="content">${heading('응대 모드·검수','충분히 확인한 문의 유형부터 자동화를 검토하세요.',`<button class="btn ${state.emergency?'pale':'danger-outline'}" data-action="emergency" ${state.role!=='admin'?'disabled':''}>${icon('shield')}${state.emergency?'자동 발송 중지 해제':'자동 발송 긴급 중지'}</button>`)}${state.emergency?'<div class="alert amber">자동 발송이 중지된 상태입니다. 담당자 검토와 직접 답변은 계속할 수 있습니다.</div>':''}<div class="two-column"><section class="panel"><header><div><h2>문의 유형별 운영 모드</h2><p>재고·납기·보증·근거 부족 문의는 담당자 확인을 유지합니다.</p></div></header><div class="mode-list">${categories.map(c=>`<div class="mode-row"><div><strong>${c}</strong><small>${c==='견적·납기'||c==='A/S·점검'?'확정 조건은 담당자 검토 필수':'공개 근거와 적용 제품 확인 후 전환 검토'}</small></div><select class="select" data-input="mode" data-category="${c}" aria-label="${c} 응대 모드" ${state.role!=='admin'?'disabled':''}><option value="manual" ${state.modes[c]==='manual'?'selected':''}>수동 응대</option><option value="assisted" ${state.modes[c]==='assisted'?'selected':''}>반자동 · 승인</option><option value="auto" ${state.modes[c]==='auto'?'selected':''}>자동 · 검수</option></select></div>`).join('')}</div><div class="panel-note">자동 모드에서도 검수 미통과·오류·추가 질문은 보류하고 담당자에게 넘깁니다.</div></section><section class="panel"><header><div><h2>발송 전 검수 기준</h2><p>근거와 공개 범위를 먼저 확인합니다.</p></div>${badge('항상 적용','blue')}</header><div class="guard-list">${[['공개 근거 일치','활성 문서와 답변 내용, 적용 제품 확인'],['질문과 답변의 누락','필수 정보가 없으면 재질문 또는 보류'],['사내 전용 정보 제외','개인 정보와 거래처별 조건 공개 차단'],['미확인 조건 차단','가격·재고·납기·보증 조건 추측 금지'],['신규 메시지 확인','승인 후 새 문의 수신 시 재검토']].map(([t,d])=>`<div>${icon('checkCircle')}<span><strong>${t}</strong><small>${d}</small></span></div>`).join('')}</div></section></div>${channelModePanel()}<section class="panel spacing"><header><div><h2>자동 전환 평가</h2><p>실제 전환은 합의된 평가와 운영 관찰, 관리자 승인을 거칩니다.</p></div><button class="btn pale" data-action="evaluation" ${state.role!=='admin'?'disabled':''}>${icon('chart')}평가 시나리오 체험</button></header><div class="evaluation-block"><div class="evaluation-score"><small>샘플 평가 결과</small><strong>${e?e.passed:'—'}<span>${e?' / 100문항':'아직 실행하지 않았어요'}</span></strong>${e?badge(eligible?'설정된 평가 조건 충족':'추가 개선 필요',eligible?'blue':'amber'):badge('실제 정확도 측정 전')}</div><div class="evaluation-details"><label for="threshold">자동 전환 검토 기준</label><div><input class="input threshold" id="threshold" type="number" min="95" max="100" value="${state.threshold}" ${state.role!=='admin'?'readonly':''}><span>% 이상 · 공개 범위 위반 0건</span><button class="btn" data-action="threshold" ${state.role!=='admin'?'disabled':''}>저장</button></div><p>${e?`근거 내 안내 ${e.passed}건 · 보류 ${100-e.passed}건 · 공개 범위 위반 ${e.critical}건`:'고정된 샘플 평가 시나리오로 전환 검토 화면을 체험할 수 있습니다.'}</p><small>샘플 결과는 실제 LLM 평가나 정확도 보장이 아닙니다.</small></div></div><div class="rollout"><span class="active">1. 담당자 승인 운영</span>${icon('arrow')}<span>2. 오류·지식 개선 및 관찰</span>${icon('arrow')}<span>3. 유형별 자동 전환 승인</span></div></section>${footer()}</div>`;}
function reports(){const list=visiblePeriod(),completed=list.filter(t=>t.status==='sent').length,total=list.length;return `<div class="content">${heading('분석 리포트','문의 유형과 보류 사유를 살펴보고 응대 기준을 보완하세요.',`<button class="btn" data-action="export">${icon('download')}CSV 내보내기</button>${periodSelect()}`)}<div class="metrics">${[['전체 문의',total,'건','inbox'],['답변 완료',completed,'건','check'],['처리 완료 비중',total?(completed/total*100).toFixed(1):0,'%','chart'],['확인 필요',list.filter(t=>['held','assigned','failed'].includes(t.status)).length,'건','shield']].map(([n,v,u,i])=>`<article class="metric"><span>${n}<i>${icon(i)}</i></span><strong>${v}<small>${u}</small></strong><p>선택 기간의 샘플 문의 기준</p></article>`).join('')}</div><div class="two-column"><section class="panel"><header><div><h2>문의 유형별 분포</h2><p>제품·소모품·견적·서비스 문의를 분류합니다.</p></div></header><div class="distribution">${categories.map(c=>{const n=list.filter(t=>t.category===c).length;return `<div><span>${c}</span><i><b style="width:${total?n/total*100:0}%"></b></i><strong>${n}건</strong></div>`;}).join('')}</div></section><section class="panel"><header><div><h2>담당자 확인이 필요한 사유</h2><p>자동 답변보다 추가 확인이 필요한 문의입니다.</p></div></header><div class="reason-list">${[['근거·호환 정보 부족',list.filter(t=>t.rag==='insufficient').length],['제품·모델 확인 필요',list.filter(t=>t.rag==='clarify').length],['가격·서비스·첨부 직접 확인',list.filter(t=>t.rag==='manual').length],['사내 정보 공개 차단',list.filter(t=>t.rag==='restricted').length],['발송 실패',list.filter(t=>t.status==='failed').length]].map(([t,n])=>`<div><span>${t}</span><strong>${n}<small>건</small></strong></div>`).join('')}</div></section></div><section class="panel spacing"><header><div><h2>응대 품질과 수정 사례</h2><p>발송 승인과 공통 지식 반영을 각각 확인합니다.</p></div></header><div class="quality-grid">${[['수정 사례',state.feedback.length,'건'],['지식 반영',state.feedback.filter(f=>f.status==='accepted').length,'건'],['반영 검토',state.feedback.filter(f=>f.status==='pending').length,'건'],['공통 지식 제외',state.feedback.filter(f=>f.status==='excluded'||f.status==='held').length,'건']].map(([t,n,u])=>`<div><span>${t}</span><strong>${n}<small>${u}</small></strong></div>`).join('')}</div><div class="panel-note">정확도·수정률·응답 시간의 실제 성과는 운영 데이터 수집 후 측정합니다. 이 화면은 샘플 운영 데이터입니다.</div></section>${footer()}</div>`;}
function connections(){return `<div class="content">${heading('채널·운영 상태','접수부터 발송까지의 연결 상태와 예외 처리를 관리하세요.')}<div class="connection-grid">${Object.entries(channels).map(([key,c])=>`<article class="panel connection-card"><div>${ch(key)}${badge(state.paused.includes(key)?'데모 일시 중지':'샘플 연결',state.paused.includes(key)?'amber':'blue')}</div><h2>${c.detail}</h2><p>${c.account}</p><dl><dt>수신 문의</dt><dd>${state.threads.filter(t=>t.channel===key).length}건</dd><dt>응답 방식</dt><dd>${key==='web'?'이메일 회신':'같은 채널 회신'}</dd><dt>실제 인증</dt><dd>연결 전</dd></dl><footer><button class="btn" data-action="channel-config" data-channel="${key}">연동 설정</button><button class="text-button" data-action="channel-toggle" data-channel="${key}" ${state.role!=='admin'?'disabled':''}>${state.paused.includes(key)?'데모 재개':'일시 중지'}</button></footer></article>`).join('')}</div><div class="two-column spacing"><section class="panel"><header><div><h2>주·예비 모델 운영</h2><p>주 모델 장애 시 예비 모델로 전환하는 구성입니다.</p></div>${badge(state.modelFailure?'예비 모델 사용':'주 모델 구성','blue')}</header><div class="model-pair"><div><span>주 모델</span><strong>GPT</strong><small>${state.modelFailure?'장애 시나리오':'모델 상세 선정 전'}</small></div>${icon('arrow')}<div><span>예비 모델</span><strong>Claude</strong><small>동일한 공개 근거와 검수 적용</small></div></div><div class="panel-action"><button class="btn" data-action="model-failure" ${state.role!=='admin'?'disabled':''}>${state.modelFailure?'주 모델 복구 시나리오':'주 모델 장애 시나리오'}</button></div><div class="panel-note">실제 LLM 호출은 연결되지 않았습니다. 모델 정책과 전환 흐름의 데모입니다.</div></section><section class="panel"><header><div><h2>수신·발송 예외 처리</h2><p>중복 수신과 발송 실패를 구분해 처리합니다.</p></div></header><div class="reason-list"><div><span>중복 이벤트 제외</span><strong>${state.duplicates}<small>건 · 샘플</small></strong></div><div><span>발송 실패</span><strong>${count('failed')}<small>건</small></strong></div></div><div class="panel-action split"><button class="btn" data-action="duplicate" ${isReadonly()?'disabled':''}>중복 수신 시나리오</button><button class="btn pale" data-action="failed-queue">실패 문의 확인${icon('arrow')}</button></div></section></div>${footer()}</div>`;}
function audit(){const list=state.auditFilter==='all'?state.audit:state.audit.filter(a=>a.kind===state.auditFilter);return `<div class="content">${heading('처리 이력','초안 수정·승인·발송과 지식 반영의 처리자를 확인하세요.',`<select class="select" data-input="audit-filter" aria-label="처리 이력 유형"><option value="all">모든 작업</option>${[...new Set(state.audit.map(a=>a.kind))].map(k=>`<option ${state.auditFilter===k?'selected':''}>${esc(k)}</option>`).join('')}</select>`)}<section class="panel"><div class="table-scroll"><table><thead><tr><th>처리 시점</th><th>처리자</th><th>작업</th><th>대상</th><th>처리 내용</th></tr></thead><tbody>${list.map(a=>`<tr><td class="nowrap">${esc(a.time)}</td><td>${esc(a.actor)}</td><td>${badge(a.kind,a.kind==='실패'?'red':a.kind==='승인'?'blue':'')}</td><td>${esc(a.target)}</td><td>${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div><div class="panel-note">데모 이력은 현재 브라우저에 저장됩니다. 실제 감사 로그와 권한 검증은 구축 시 서버에 연결합니다.</div></section>${footer()}</div>`;}
function settings(){return `<div class="content">${heading('사용자·운영 설정','회사 응대 기준과 기능별 접근 권한을 확인하세요.')}<div class="two-column"><section class="panel"><header><div><h2>회사 응대 기준</h2><p>제품·문서·공개 범위를 우선해 초안을 작성합니다.</p></div></header><div class="form-section"><label class="field-label" for="guidance">답변 작성 원칙</label><textarea class="textarea" id="guidance" rows="6" ${state.role!=='admin'?'readonly':''}>${esc(state.guidance)}</textarea><div class="guidance-note">지침 저장은 데모 구성 변경입니다. 실제 LLM 프롬프트 호출·학습은 실행하지 않습니다.</div><button class="btn primary" data-action="save-guidance" ${state.role!=='admin'?'disabled':''}>응대 기준 저장</button></div></section><section class="panel"><header><div><h2>역할별 접근 권한</h2><p>현재 권한은 ${actor().role}입니다.</p></div><button class="text-button" data-action="profile">데모 권한 변경${icon('arrow')}</button></header><div class="permission-table"><table><thead><tr><th>기능</th><th>관리자</th><th>검토 담당</th><th>조회</th></tr></thead><tbody>${[['문의·공개 문서 조회',1,1,1],['답변 수정·승인·발송',1,1,0],['공통 지식 반영 승인',1,0,0],['사내 전용 문서 조회',1,0,0],['자동 전환·운영 설정',1,0,0]].map(([t,...v])=>`<tr><td>${t}</td>${v.map(x=>`<td>${x?icon('check'):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="panel-note">권한 차이를 체험하는 프런트엔드 데모이며 실제 로그인·서버 접근 제어는 연결되어 있지 않습니다.</div></section></div><section class="panel spacing"><header><div><h2>데모 데이터</h2><p>작업한 내용은 이 브라우저에 저장되며 다른 사용자와 공유되지 않습니다.</p></div><button class="btn" data-action="reset" ${state.role!=='admin'?'disabled':''}>샘플 초기화</button></header><div class="form-section"><p class="muted">가상 장비 모델·문의·문서로 화면을 구성했습니다. 실제 매뉴얼과 채널 계정, 고객 이력은 연결되어 있지 않습니다.</p></div></section>${footer()}</div>`;}
